// ─────────────────────────────────────────────────────────────────
// MASTER CONFIG — fill in Drive folder IDs + Odoo account IDs once
// Get Drive folder IDs from the URL when you open each folder:
//   drive.google.com/drive/folders/THIS_IS_THE_ID
// Get Odoo social account IDs:
//   Odoo → Social Marketing → Social Accounts → click account → check URL
// ─────────────────────────────────────────────────────────────────
const businesses = [
  {
    name: 'Long Island Convenience',
    websiteKeyword: 'long island',
    driveFolderId: 'FILL_IN_LONGISLAND_DRIVE_FOLDER_ID',
    drivePostedFolderId: 'FILL_IN_LONGISLAND_POSTED_FOLDER_ID',
    odooAccountIds: [],  // FILL IN after connecting FB/IG in Odoo Social Marketing
    claudeSystemPrompt: 'You are a viral social media expert for Country Cove Long Island, a one-stop convenience hub in Plainview, Long Island NY. They sell gift baskets, balloons, sports cards, greeting cards, cigars, and document services. Local Long Island community feel.',
    hashtags: '#longisland #plainviewny #shoplocal #longislandbusiness #nassaucounty #longislandlife #shopsmall #countrycovelongisland #longislandshops #visitlongisland #supportlocal #longislandgifts'
  },
  {
    name: 'Country Cove Balloons',
    websiteKeyword: 'balloon',
    driveFolderId: '1QSAOTPFBIg-kYlnSg3mchq2VU0cvFFb8',
    drivePostedFolderId: 'FILL_IN_BALLOONS_POSTED_FOLDER_ID',
    odooAccountIds: [],
    claudeSystemPrompt: 'You are a viral social media expert for Country Cove Balloons, a luxury balloon decoration business in Plainview, Long Island NY. Focus on emotions, celebrations, birthdays, graduations, events.',
    hashtags: '#balloon #balloonart #balloondecorations #birthdayballoons #partyballoons #balloonbouquet #eventdecor #balloondesign #longisland #plainviewny #balloondelivery #graduation2026 #partyplanning'
  },
  {
    name: 'Country Cove Sports Cards',
    websiteKeyword: 'sports',
    driveFolderId: 'FILL_IN_SPORTSCARDS_DRIVE_FOLDER_ID',
    drivePostedFolderId: 'FILL_IN_SPORTSCARDS_POSTED_FOLDER_ID',
    odooAccountIds: [],
    claudeSystemPrompt: 'You are a viral social media expert for Country Cove Sports Cards in Plainview Long Island NY. They sell PSA graded cards, raw sports cards, Pokémon, MTG, Yu-Gi-Oh. Speak to collectors and investors.',
    hashtags: '#sportscards #psagraded #cardcollector #pokemoncards #tradingcards #longisland #plainviewny #baseballcards #basketballcards #footballcards #mtg #yugioh #collectibles'
  },
  {
    name: 'Country Cove Greeting Cards',
    websiteKeyword: 'greeting',
    driveFolderId: 'FILL_IN_GREETINGCARDS_DRIVE_FOLDER_ID',
    drivePostedFolderId: 'FILL_IN_GREETINGCARDS_POSTED_FOLDER_ID',
    odooAccountIds: [],
    claudeSystemPrompt: 'You are a viral social media expert for Country Cove Greeting Cards in Plainview Long Island NY. Physical greeting cards, digital e-cards, and monthly card club membership. Emotional, warm, heartfelt tone.',
    hashtags: '#greetingcards #sendacard #handmadecards #longisland #plainviewny #birthdaycard #anniversarycard #cardmaking #digitalcard #thoughtfulgiving #cardclub'
  },
  {
    name: 'Country Cove Gift Baskets',
    websiteKeyword: 'gift basket',
    driveFolderId: 'FILL_IN_GIFTBASKETS_DRIVE_FOLDER_ID',
    drivePostedFolderId: 'FILL_IN_GIFTBASKETS_POSTED_FOLDER_ID',
    odooAccountIds: [],
    claudeSystemPrompt: 'You are a viral social media expert for Country Cove Gift Baskets in Plainview Long Island NY. Curated gift baskets for graduation, Father Day, birthdays, corporate. Free Long Island delivery. Emotional gifting tone.',
    hashtags: '#giftbasket #giftbaskets #longisland #graduation2026 #fathersday #corporategifts #plainviewny #gifting #birthdaygift #shoplocal #longislanddelivery #handcrafted'
  },
  {
    name: 'Country Cove Cigars',
    websiteKeyword: 'cigar',
    driveFolderId: 'FILL_IN_CIGARS_DRIVE_FOLDER_ID',
    drivePostedFolderId: 'FILL_IN_CIGARS_POSTED_FOLDER_ID',
    odooAccountIds: [],
    claudeSystemPrompt: 'You are a social media expert for Country Cove Cigars and Smoke in Plainview Long Island NY. Premium cigars, smokeshop products, and CBD. Clean, sophisticated, no explicit language. Adults 21+ only. Strong brand impression.',
    hashtags: '#cigars #premiumcigars #longisland #plainviewny #cigarlife #smokeshop #cbd #adultonly #cigarlounge #tobaccoshop'
  },
  {
    name: 'Country Cove Print Copy',
    websiteKeyword: 'print',
    driveFolderId: 'FILL_IN_PRINTCOPY_DRIVE_FOLDER_ID',
    drivePostedFolderId: 'FILL_IN_PRINTCOPY_POSTED_FOLDER_ID',
    odooAccountIds: [],
    claudeSystemPrompt: 'You are a social media expert for Country Cove Print and Copy in Plainview Long Island NY. Color printing, copying, faxing, scanning services. Professional, helpful, local community tone.',
    hashtags: '#printing #copyshop #longisland #plainviewny #documentsservices #printservices #businessservices #shoplocal #officeservices'
  }
];

// Return as separate items — n8n processes each one in the loop
return businesses.map(b => ({ json: b }));

// ── Duplicate detection using n8n static data (free, no external DB) ──
const staticData = $getWorkflowStaticData('global');
const postedFiles = staticData.postedFiles || {};

// Get business config from the loop item
const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No Drive response received');
}

// Find the business config — it's the item that has driveFolderId
// (comes from the batch, not the Drive node)
const batchItem = $('Loop Over Businesses').item?.json;
if (!batchItem) throw new Error('Cannot read business config from batch');

const businessName = batchItem.name;

// Get files from Drive response
const files = items
  .map(i => i.json)
  .filter(f => f && f.id && f.name)
  .filter(f => /\.(mp4|mov|avi|mkv|webm)$/i.test(f.name)); // videos only

if (files.length === 0) {
  return [{ json: {
    hasVideo: false,
    businessName,
    reason: 'No video files in Drive folder',
    config: batchItem
  }}];
}

// Find first file NOT already posted
const alreadyPosted = postedFiles[businessName] || [];
const unpostedFile = files.find(f => !alreadyPosted.includes(f.id));

if (!unpostedFile) {
  return [{ json: {
    hasVideo: false,
    businessName,
    reason: 'All videos in folder already posted. Add new content.',
    config: batchItem
  }}];
}

return [{ json: {
  hasVideo: true,
  businessName,
  fileId: unpostedFile.id,
  filename: unpostedFile.name,
  config: batchItem
}}];

// ── Parse Claude response safely ──
const raw = $input.first().json.text || $input.first().json?.content?.[0]?.text || '';
if (!raw) throw new Error('Claude returned empty response');

let ai;
try {
  // Extract JSON even if Claude wrapped it in markdown
  const match = raw.match(/\{[\s\S]*?\}(?=[\s]*$)/m) || raw.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('No JSON object found in Claude response: ' + raw.substring(0, 200));
  ai = JSON.parse(match[0]);
} catch(e) {
  throw new Error('JSON parse failed: ' + e.message + ' | Raw: ' + raw.substring(0, 300));
}

if (!ai.title || !ai.caption) {
  throw new Error('Claude JSON missing required fields. Got: ' + JSON.stringify(Object.keys(ai)));
}

// Get data from previous nodes
const videoInfo = $('Find Unposted Video + Duplicate Check').item.json;
const config = videoInfo.config;

// Build post text
const fullText = ai.title + '\n\n' + ai.caption + '\n\n' + (ai.hashtags || config.hashtags);

// Instagram hard limit = 2200 chars, Facebook = 63206 chars
// Use 2000 to be safe with all platforms
const safeText = fullText.length > 2000 
  ? fullText.substring(0, 1950) + '...'
  : fullText;

return [{ json: {
  fileId: videoInfo.fileId,
  filename: videoInfo.filename,
  businessName: videoInfo.businessName,
  config: config,
  postText: safeText,
  Title: ai.title
} }];

// ── Validate Cloudinary upload succeeded ──
const cloudRes = $input.first().json;
const videoUrl = cloudRes.secure_url;

if (!videoUrl || !videoUrl.startsWith('https://')) {
  throw new Error(
    'Cloudinary upload failed. Response: ' + JSON.stringify(cloudRes).substring(0, 300) +
    '\nCheck: 1) cloud_name correct 2) upload_preset exists and is unsigned 3) free tier not exceeded'
  );
}

const postData = $('Build Post Data').item.json;

return [{ json: {
  videoUrl,
  postText: postData.postText,
  businessName: postData.businessName,
  config: postData.config,
  fileId: postData.fileId,
  filename: postData.filename
} }];

// ── Robust cookie extraction with full validation ──
const res = $input.first().json;

// Try to get uid from body
const body = res.body || res;
const uid = body?.result?.uid;
if (!uid) {
  const errMsg = body?.error?.data?.message || JSON.stringify(body).substring(0, 200);
  throw new Error('Odoo auth failed — uid not returned. Error: ' + errMsg + '\nCheck: email/password correct, Odoo not in maintenance');
}

// Extract session_id from Set-Cookie header (multiple possible header formats)
let sessionCookie = '';
const headers = res.headers || {};

// Header key can be 'set-cookie', 'Set-Cookie', or an array
const rawCookie = headers['set-cookie'] || headers['Set-Cookie'] || '';
const cookieArr = Array.isArray(rawCookie) ? rawCookie : [rawCookie];

for (const c of cookieArr) {
  const match = c.match(/session_id=([^;]+)/);
  if (match) {
    sessionCookie = 'session_id=' + match[1];
    break;
  }
}

// If no cookie from header, try body result
if (!sessionCookie && body?.result?.session_id) {
  sessionCookie = 'session_id=' + body.result.session_id;
}

if (!sessionCookie) {
  throw new Error(
    'Odoo session cookie not found. uid=' + uid +
    ' Headers available: ' + Object.keys(headers).join(', ') +
    '\nTry: Settings → Technical → API Keys → create one and use as password'
  );
}

// Pass forward all needed data
const prev = $('Validate Upload + Build Odoo Auth').item.json;
return [{ json: {
  sessionCookie,
  uid,
  videoUrl: prev.videoUrl,
  postText: prev.postText,
  businessName: prev.businessName,
  config: prev.config,
  fileId: prev.fileId,
  filename: prev.filename
} }];

// ── STRICT account resolution — NO FALLBACK TO ALL ACCOUNTS ──
const odooRes = $input.first().json;
const allAccounts = odooRes?.result || [];

const prev = $('Extract + Validate Odoo Session').item.json;
const config = prev.config;
const businessName = prev.businessName;

if (allAccounts.length === 0) {
  throw new Error(
    'No social accounts found in Odoo for ' + businessName + '.\n' +
    'Action: Odoo → Social Marketing → Add Account → connect Facebook/Instagram'
  );
}

// Strategy 1: Use hardcoded IDs from config (most reliable)
let accountIds = config.odooAccountIds || [];

// Strategy 2: If no hardcoded IDs, filter by website name (strict match)
if (accountIds.length === 0) {
  const keyword = (config.websiteKeyword || '').toLowerCase();
  const matched = allAccounts.filter(a => {
    if (a.is_media_disconnected) return false; // skip disconnected accounts
    const siteName = (a.website_id?.[1] || '').toLowerCase();
    const acctName = (a.name || '').toLowerCase();
    return siteName.includes(keyword) || acctName.includes(keyword);
  });
  accountIds = matched.map(a => a.id);
}

// HARD STOP — never post to wrong accounts
if (accountIds.length === 0) {
  throw new Error(
    'Cannot find Odoo social accounts for: ' + businessName + '\n' +
    'Keyword searched: "' + config.websiteKeyword + '"\n' +
    'Available accounts: ' + allAccounts.map(a => a.name + '(id:' + a.id + ')').join(', ') + '\n\n' +
    'Fix: Either 1) Fill odooAccountIds in business config OR 2) Name the account to include "' + config.websiteKeyword + '" OR 3) Connect account in Odoo Social Marketing'
  );
}

// Check for disconnected accounts
const disconnected = allAccounts.filter(a => accountIds.includes(a.id) && a.is_media_disconnected);
if (disconnected.length > 0) {
  throw new Error(
    'Social accounts disconnected for ' + businessName + ': ' +
    disconnected.map(a => a.name).join(', ') +
    '\nFix: Odoo → Social Marketing → reconnect the account'
  );
}

console.log('[' + businessName + '] Posting to account IDs:', accountIds);

return [{ json: {
  sessionCookie: prev.sessionCookie,
  accountIds,
  postText: prev.postText,
  videoUrl: prev.videoUrl,
  businessName,
  config,
  fileId: prev.fileId,
  filename: prev.filename
} }];

// ── Build proper Odoo JSON-RPC create request ──
// Note: we build this in a Code node to avoid JSON-in-string expression issues
const prev = $input.first().json;

// Build the many2many command: [[6, 0, [id1, id2, ...]]] = replace all with these IDs
const accountCommand = [[6, 0, prev.accountIds]];

// Full message with video link
const message = prev.postText + '\n\n▶️ ' + prev.videoUrl;

const requestBody = {
  jsonrpc: '2.0',
  method: 'call',
  id: 3,
  params: {
    model: 'social.post',
    method: 'create',
    args: [{
      account_ids: accountCommand,
      message: message
    }],
    kwargs: {}
  }
};

return [{ json: {
  requestBody: JSON.stringify(requestBody),
  sessionCookie: prev.sessionCookie,
  businessName: prev.businessName,
  config: prev.config,
  fileId: prev.fileId,
  filename: prev.filename,
  accountIds: prev.accountIds
} }];

const res = $input.first().json;
const postId = res?.result;

if (!postId || typeof postId !== 'number' || postId <= 0) {
  const errDetail = res?.error?.data?.message || JSON.stringify(res).substring(0, 300);
  throw new Error('Failed to create social.post in Odoo. Detail: ' + errDetail);
}

const prev = $('Build Odoo Post Request').item.json;
return [{ json: {
  postId,
  sessionCookie: prev.sessionCookie,
  businessName: prev.businessName,
  config: prev.config,
  fileId: prev.fileId,
  filename: prev.filename
} }];

const statusRes = $input.first().json;
const postInfo = statusRes?.result?.[0];
const prevData = $('Extract Post ID').item.json;

if (!postInfo) {
  throw new Error('Could not read post status from Odoo. Post ID: ' + prevData.postId);
}

// Check for failure
if (postInfo.failure_reason) {
  throw new Error(
    'Post FAILED on platform for ' + prevData.businessName + '.\n' +
    'Odoo post ID: ' + prevData.postId + '\n' +
    'Failure: ' + postInfo.failure_reason + '\n' +
    'Fix: Odoo → Social Marketing → reconnect social account token'
  );
}

// ── Mark file as posted in static data (duplicate prevention) ──
const staticData = $getWorkflowStaticData('global');
const postedFiles = staticData.postedFiles || {};
const businessName = prevData.businessName;

if (!postedFiles[businessName]) postedFiles[businessName] = [];

// Keep last 30 posted file IDs per business (prevent unbounded growth)
postedFiles[businessName].push(prevData.fileId);
if (postedFiles[businessName].length > 30) {
  postedFiles[businessName] = postedFiles[businessName].slice(-30);
}
staticData.postedFiles = postedFiles;

console.log('[' + businessName + '] ✅ Post published. State: ' + postInfo.state + ' | FileId marked as posted.');

return [{ json: {
  status: 'SUCCESS',
  businessName,
  postId: prevData.postId,
  odooState: postInfo.state,
  filename: prevData.filename,
  fileId: prevData.fileId,
  config: prevData.config,
  sessionCookie: prevData.sessionCookie,
  odooUrl: 'https://country-cove-inc.odoo.com/web#model=social.post&id=' + prevData.postId,
  timestamp: new Date().toLocaleString('en-US', {timeZone: 'America/New_York'})
} }];

// Collect result from whichever branch ran (success or no-video)
const item = $input.first().json;
return [{ json: {
  businessName: item.businessName || 'unknown',
  status: item.status || 'SKIPPED',
  reason: item.reason || null,
  postId: item.postId || null,
  odooUrl: item.odooUrl || null,
  filename: item.filename || null,
  timestamp: item.timestamp || new Date().toLocaleString('en-US', {timeZone: 'America/New_York'})
} }];

const results = $input.all().map(i => i.json);

const successes = results.filter(r => r.status === 'SUCCESS');
const skipped = results.filter(r => r.status === 'SKIPPED');
const failed = results.filter(r => r.status === 'FAILED');

let summary = '📊 Country Cove Daily Post Report\n';
summary += new Date().toLocaleString('en-US', {timeZone: 'America/New_York'}) + '\n\n';
summary += '✅ Posted: ' + successes.length + '/7\n';
if (successes.length > 0) {
  summary += successes.map(r => '  • ' + r.businessName + ': ' + (r.filename || '') ).join('\n') + '\n';
}
if (skipped.length > 0) {
  summary += '\n⏭️ Skipped (' + skipped.length + '):\n';
  summary += skipped.map(r => '  • ' + r.businessName + ': ' + r.reason).join('\n') + '\n';
}
if (failed.length > 0) {
  summary += '\n❌ Failed (' + failed.length + '):\n';
  summary += failed.map(r => '  • ' + r.businessName + ': ' + r.reason).join('\n') + '\n';
}
summary += '\n—\nCountry Cove Auto-Publisher';

return [{ json: { summaryText: summary } }];
